#!/bin/bash
# Print the three most frequent IPs from access.log, most frequent first,
# breaking ties by first appearance in the log.
awk '
{
    ip = $1
    count[ip]++
    if (!(ip in first_seen)) {
        first_seen[ip] = NR
        order[++n] = ip
    }
}
END {
    # Simple selection sort: pick top 3 by count desc, first-seen asc
    for (i = 1; i <= 3; i++) {
        best = 0
        for (j = 1; j <= n; j++) {
            if (picked[j]) continue
            if (best == 0) { best = j; continue }
            b = order[best]; c = order[j]
            if (count[c] > count[b] || (count[c] == count[b] && first_seen[c] < first_seen[b]))
                best = j
        }
        print order[best]
        picked[best] = 1
    }
}
' access.log
